<h1>Cadastro de clientes</h1><section class="panel"><h2><?= $edit ? 'Editar cliente' : 'Novo cliente' ?></h2><form method="post" action="?pagina=clientes&acao=salvar" class="grid"><?php if($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><?php endif; ?><label>Nome *<input name="nome" required maxlength="120" value="<?= e($edit['nome'] ?? '') ?>"></label><label>CPF<input name="cpf" maxlength="14" value="<?= e($edit['cpf'] ?? '') ?>"></label><label>Telefone<input name="telefone" value="<?= e($edit['telefone'] ?? '') ?>"></label><label>E-mail<input type="email" name="email" value="<?= e($edit['email'] ?? '') ?>"></label><button>Salvar cliente</button><?php if($edit): ?><a href="?pagina=clientes">Cancelar</a><?php endif; ?></form></section>
<section class="panel"><h2>Clientes cadastrados</h2><div class="table-wrap"><table><tr><th>Nome</th><th>CPF</th><th>Telefone</th><th>E-mail</th><th>Ações</th></tr><?php foreach($clientes as $c): ?><tr><td><?= e($c['nome']) ?></td><td><?= e($c['cpf']) ?></td><td><?= e($c['telefone']) ?></td><td><?= e($c['email']) ?></td><td><a href="?pagina=clientes&editar=<?= (int)$c['id'] ?>">Editar</a> <form method="post" action="?pagina=clientes&acao=excluir" onsubmit="return confirm('Excluir cliente?')"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button class="danger">Excluir</button></form></td></tr><?php endforeach; ?></table></div></section>
